    inline float silu(float x) { return x / (1.0f + expf(-x)); }
    inline float clamp(float x, float lo, float hi) {
        if (!isfinite(x)) return 0.5f * (lo + hi);
        return x < lo ? lo : (x > hi ? hi : x);
    }

    inline void compute_bsplines(float x_in, float* basis) {
        float x = x_in;
        if(x < -2.5f) x = -2.5f;
        if(x > 2.5f) x = 2.5f;
        const int G = 10;
        float grid[G + 7];
        for(int i=0; i<G+7; i++) grid[i] = -3.2f + i*0.4f;
        float b_curr[G+6];
        for(int i=0; i<G+6; i++) b_curr[i] = 0.0f;
        for(int i=0; i<G+6; i++) if(x >= grid[i] && x < grid[i+1]) b_curr[i] = 1.0f;
        for(int p=1; p<=3; p++) {
            float b_next[G+6];
            for(int i=0; i<G+6-p; i++) {
                float d1 = grid[i+p] - grid[i];
                float d2 = grid[i+p+1] - grid[i+1];
                float t1 = (d1 < 1e-8f) ? 0.0f : (x - grid[i]) / d1 * b_curr[i];
                float t2 = (d2 < 1e-8f) ? 0.0f : (grid[i+p+1] - x) / d2 * b_curr[i+1];
                b_next[i] = t1 + t2;
            }
            for(int i=0; i<G+6-p; i++) b_curr[i] = b_next[i];
        }
        for(int i=0; i<G+3; i++) basis[i] = b_curr[i];
    }

